create extension if not exists pgcrypto;
create function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at = now(); return new; end $$;

create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, email text, full_name text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.documents (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, external_document_id text, title text, source text not null default 'word', metadata jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.chat_sessions (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, document_id uuid references public.documents(id) on delete set null, title text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.messages (id uuid primary key default gen_random_uuid(), session_id uuid not null references public.chat_sessions(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, role text not null check(role in ('user','assistant','system')), action text, content text not null default '', selected_text text, document_context text, citations jsonb not null default '[]', warnings jsonb not null default '[]', metadata jsonb not null default '{}', created_at timestamptz not null default now());
create table public.mcp_tool_calls (id uuid primary key default gen_random_uuid(), session_id uuid not null references public.chat_sessions(id) on delete cascade, message_id uuid references public.messages(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, tool_name text not null, request_payload jsonb, response_payload jsonb, status text not null check(status in ('success','error','mocked','skipped')), error_message text, duration_ms integer, created_at timestamptz not null default now());
create table public.webhook_tool_calls (id uuid primary key default gen_random_uuid(), session_id uuid not null references public.chat_sessions(id) on delete cascade, message_id uuid references public.messages(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, tool_name text not null, status text not null check(status in ('success','error','mocked','skipped')), response_summary text, duration_ms integer, created_at timestamptz not null default now());

create index documents_user_idx on public.documents(user_id); create index sessions_user_idx on public.chat_sessions(user_id); create index messages_user_created_idx on public.messages(user_id, created_at desc); create index mcp_calls_user_idx on public.mcp_tool_calls(user_id); create index webhook_calls_user_idx on public.webhook_tool_calls(user_id);
create trigger profiles_updated before update on public.profiles for each row execute function public.set_updated_at(); create trigger documents_updated before update on public.documents for each row execute function public.set_updated_at(); create trigger sessions_updated before update on public.chat_sessions for each row execute function public.set_updated_at();

alter table public.profiles enable row level security; alter table public.documents enable row level security; alter table public.chat_sessions enable row level security; alter table public.messages enable row level security; alter table public.mcp_tool_calls enable row level security; alter table public.webhook_tool_calls enable row level security;
create policy profiles_own on public.profiles for all using (auth.uid() = id) with check (auth.uid() = id);
create policy documents_own on public.documents for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy sessions_own on public.chat_sessions for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy messages_own on public.messages for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy mcp_calls_own on public.mcp_tool_calls for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy webhook_calls_own on public.webhook_tool_calls for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
